
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_lbm_N_2_vrho():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_lbm", 2)
    if not feval._have_vxc:
        pytest.skip("build lacks the derivative order for vrho")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=feval._have_vxc, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["vrho"])
    tgt = out["vrho"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-6.976785092178539e+00, -6.976971906873484e+00, -6.848580258737679e+00, -6.848836103550963e+00, -6.669135172404305e+00, -6.669477821152721e+00, -6.420974725667698e+00, -6.421419395746542e+00, -6.083679578448191e+00, -6.084234469289701e+00, -5.636497901757050e+00, -5.637176425186161e+00, -5.064306666554699e+00, -5.065256729105206e+00, -4.367721845102431e+00, -4.369991572016588e+00, -3.573645723245346e+00, -3.583215844230787e+00, -2.725079148209280e+00, -2.771338084541879e+00, -1.826464381550963e+00, -1.969536475794444e+00, -1.203334939158250e+00, -1.011587781649421e+00, -1.046744282834453e+00, -6.935127616289292e-01, -8.786730975064180e-01, -6.299848961380334e-01, -6.558349639411700e-01, -5.013912612131178e-01, -4.448389773917703e-01, -3.608730632381361e-01, -2.878067403260074e-01, -2.463891606694687e-01, -1.835992987527761e-01, -1.660480886096380e-01, -1.216429770925816e-01, -1.158284973161947e-01, -8.329620060276165e-02, -8.151783913313443e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-05


